        "add", "remove", "pick", "open", "close", "get",
        "hset", "probe", "hget", "chash", "route", "ws", "wg",
        "cs", "cr", "cg", "ds", "dr", "du", "dg",
        "ss",
        "ls", "la", "lg", "qs", "qg",
        "os", "pc", "pg", "oa", "ot", "og", "oc", "oh", "wh", "bp", "bq", "qp", "rp", "rg",
        "qa",
